// Nudges for jobs that went quiet. Reads EVERY job_feedback event and works per job:
//  status    = latest event that is not a 'nudged' marker (what the user last said)
//  lastTouch = latest event of any kind, nudges included (each nudge restarts the clock)
// applied / no_reply, quiet 7+ days -> "any reply yet?"     (replied / rejected / noreply)
// saved,              quiet 7+ days -> "still interested?"  (apply / skip / save = remind later)
// Every button goes through the Feedback workflow, so an answer is just another event.
const DAYS = 7, MAX_PER_DAY = 10;
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const now = DateTime.now();
const rows = $input.all().map(i => i.json).filter(r => r && r.archive_id !== undefined && r.archive_id !== null);
const byJob = {};
for (const r of rows) { const k = String(r.archive_id); if (!byJob[k]) byJob[k] = []; byJob[k].push(r); }
const out = [];
for (const id of Object.keys(byJob)) {
  const evs = byJob[id].slice().sort((a, b) => String(a.rated_at).localeCompare(String(b.rated_at)));
  const last = evs[evs.length - 1];
  const status = evs.slice().reverse().find(e => e.rating !== 'nudged') || last;
  const quietDays = now.diff(DateTime.fromISO(String(last.rated_at)), 'days').days;
  if (!(quietDays >= DAYS)) continue;
  const url = String(status.url || '');
  const title = esc(status.title || ('job #' + id));
  const link = url ? '<a href="' + esc(url) + '">' + title + '</a>' : title;
  const since = DateTime.fromISO(String(status.rated_at)).setZone('Asia/Bangkok').toFormat('d LLL');
  const base = { archive_id: Number(id), url, title: status.title || '', rating: 'nudged', rated_at: now.toISO(), quietDays: Math.floor(quietDays) };
  if (status.rating === 'applied' || status.rating === 'no_reply') {
    out.push({ json: { ...base, text: '📬 You applied to <b>' + link + '</b> on ' + since + ' — any reply yet?', b1: '💬 Got a reply', c1: 'fb:replied:' + id, b2: '❌ Rejected', c2: 'fb:rejected:' + id, b3: '🔕 Nothing yet', c3: 'fb:noreply:' + id } });
  } else if (status.rating === 'saved') {
    out.push({ json: { ...base, text: '🔖 You saved <b>' + link + '</b> on ' + since + ' — still interested?', b1: '✅ Apply', c1: 'fb:apply:' + id, b2: '⏭️ Skip', c2: 'fb:skip:' + id, b3: '🔖 Remind me later', c3: 'fb:save:' + id } });
  }
}
out.sort((a, b) => b.json.quietDays - a.json.quietDays);
const picked = out.slice(0, MAX_PER_DAY);
console.log('Follow-ups: ' + rows.length + ' events, ' + Object.keys(byJob).length + ' jobs, ' + out.length + ' due, sending ' + picked.length);
return picked;
